const crearMesasIniciales = (): Mesa[] =>
  Array.from({ length: 4 }, (_, index) => ({
    id: index + 1,
    nombre: `Mesa ${index + 1}`,
    estado: "Libre" as EstadoMesa,
    orden: [],
    cliente: "",
    invitados: 1,
    tipoOrden: "LOCAL" as TipoConsumo,
    cuentaDividida: false,
  }));

const formatoCRC = (monto: number) =>
  `₡${Math.round(monto || 0).toLocaleString("es-CR")}`;

const precioLinea = (item: ItemOrden) =>
  (item.precio + item.extras.reduce((acc, extra) => acc + extra.precio, 0)) * item.cantidad;

const calcularTotales = (items: ItemOrden[]) => {
  const subtotal = items.reduce((acc, item) => acc + precioLinea(item), 0);
  const baseServicio = 0;
  const servicio = 0;
  return { subtotal, servicio, total: subtotal, baseServicio };
};

const crearItem = (producto: Producto, consumo: TipoConsumo): ItemOrden => ({
  ...producto,
  uid: `${producto.id}-${Date.now()}-${Math.random().toString(36).slice(2)}`,
  cantidad: 1,
  nota: "",
  sinIngredientes: [],
  extras: [],
  consumo,
  enviadoComanda: false,
  pagado: false,
});

const inferirTipoOrden = (orden: ItemOrden[]): Mesa["tipoOrden"] => {
  if (!orden.length) return "LOCAL";
  const locales = orden.some((item) => item.consumo === "LOCAL");
  const llevar = orden.some((item) => item.consumo === "LLEVAR");
  if (locales && llevar) return "MIXTA";
  return locales ? "LOCAL" : "LLEVAR";
};

const contarProductosVendidos = (ventas: Venta[]) =>
  ventas.reduce((acc, venta) => {
    venta.items.forEach((item) => {
      acc[item.nombre] = (acc[item.nombre] || 0) + item.cantidad;
    });
    return acc;
  }, {} as Record<string, number>);

const ordenarMovimientosCronologicos = (movimientos: MovimientoCaja[] = []) =>
  [...movimientos].sort((a, b) => a.id - b.id);

const cargarLocalStorage = <T,>(clave: string, fallback: T): T => {
  try {
    const valor = localStorage.getItem(clave);
    return valor ? JSON.parse(valor) : fallback;
  } catch {
    return fallback;
  }
};

export default function App() {
  const parametrosUrl = new URLSearchParams(window.location.search);
  const mesaQR = parametrosUrl.get("mesa");
  const modoMenuQR = parametrosUrl.get("menu") === "1";

  const [usuarios, setUsuarios] = useState<Usuario[]>(() => cargarLocalStorage("gato_usuarios", usuariosIniciales));
  const [usuarioActual, setUsuarioActual] = useState<Usuario | null>(() => cargarLocalStorage("gato_usuario_actual", null));
  const [rol, setRol] = useState<Rol | null>(() => cargarLocalStorage("gato_rol", null));
  const [usuarioLogin, setUsuarioLogin] = useState("");
  const [passwordLogin, setPasswordLogin] = useState("");
  const [errorLogin, setErrorLogin] = useState("");

  const [vista, setVista] = useState<Vista>("mesas");
  const [categoriaActiva, setCategoriaActiva] = useState<CategoriaProducto>("Tacos");
  const [productos, setProductos] = useState<Producto[]>(() => cargarLocalStorage("gato_productos", productosGato));
  const [mesas, setMesas] = useState<Mesa[]>(() => cargarLocalStorage("gato_mesas", crearMesasIniciales()));
  const [mesaId, setMesaId] = useState<number | null>(null);
  const [ventas, setVentas] = useState<Venta[]>(() => cargarLocalStorage("gato_ventas", []));
  const [salidasDinero, setSalidasDinero] = useState<SalidaDinero[]>(() => cargarLocalStorage("gato_salidas", []));
  const [movimientosCaja, setMovimientosCaja] = useState<MovimientoCaja[]>(() => cargarLocalStorage("gato_movimientos", []));
  const [cierresCaja, setCierresCaja] = useState<CierreCaja[]>(() => cargarLocalStorage("gato_cierres", []));
  const [cajaActual, setCajaActual] = useState<CajaActual | null>(() => cargarLocalStorage("gato_caja_actual", null));
  const [ticketActual, setTicketActual] = useState<Ticket | null>(null);
  const [cierreDetalle, setCierreDetalle] = useState<CierreCaja | null>(null);
  const [mostrarDetalleTurno, setMostrarDetalleTurno] = useState(false);
  const [metodoPago, setMetodoPago] = useState<MetodoPago>("Efectivo");
  const [montoRecibido, setMontoRecibido] = useState(0);
  const [itemsPagoSeleccionados, setItemsPagoSeleccionados] = useState<string[]>([]);
  const [ordenQR, setOrdenQR] = useState<ItemOrden[]>([]);
  const [notaQR, setNotaQR] = useState("");
  const [nuevoProducto, setNuevoProducto] = useState<Producto>({
    id: 0,
    categoria: "Tacos",
    nombre: "",
    descripcion: "",
    precio: 0,
    ingredientes: [],
  });
  const [nuevoUsuario, setNuevoUsuario] = useState<Usuario>({ usuario: "", password: "", nombre: "", rol: "Mesero", roles: ["Mesero"] });
  const [impresoraOnline, setImpresoraOnline] = useState(false);
  const [mensajeImpresora, setMensajeImpresora] = useState("Verificando impresora local...");

  const verificarImpresoraLocal = async (mostrarMensaje = false) => {
    try {
      const controller = new AbortController();
      const timer = window.setTimeout(() => controller.abort(), PRINT_REQUEST_TIMEOUT_MS);
      const respuesta = await fetch(`${PRINT_SERVER_URL}/health`, { signal: controller.signal });
      window.clearTimeout(timer);
      const data = await respuesta.json().catch(() => null);
      if (!respuesta.ok || !data?.ok) throw new Error(data?.error || "Servicio local no disponible");
      setImpresoraOnline(Boolean(data.printerFound ?? data.printerExists ?? true));
      setMensajeImpresora(`Impresora local OK: ${data.printer || "TERMICA"}`);
      if (mostrarMensaje) alert("Impresora local conectada y lista.");
      return true;
    } catch {
      setImpresoraOnline(false);
      setMensajeImpresora("Impresora local desconectada. Instalá/abrí el servicio Gato Calavera.");
      if (mostrarMensaje) alert("No se pudo conectar con la impresora local. Revisá que el instalador de impresión esté instalado y que la impresora TERMICA esté encendida.");
      return false;
    }
  };

  useEffect(() => {
    void verificarImpresoraLocal(false);
    const intervalo = window.setInterval(() => void verificarImpresoraLocal(false), 30000);
    return () => window.clearInterval(intervalo);
  }, []);

  useEffect(() => {
    setUsuarios((prev) => prev.map(prepararUsuarioConRoles));
    setUsuarioActual((actual) => (actual ? prepararUsuarioConRoles(actual) : actual));
  }, []);

  const rolesActuales = useMemo(() => normalizarRolesUsuario(usuarioActual), [usuarioActual]);
  const rolesTextoActual = textoRolesUsuario(usuarioActual);
  const esJefe = rolesActuales.includes("Jefe");
  const esAdmin = rolesActuales.includes("Admin");
  const esCaja = rolesActuales.includes("Caja");
  const esMesero = rolesActuales.includes("Mesero");
  const esCajaOperativa = esCaja && !esAdmin && !esJefe;
  const puedeVerCajaDetallada = esJefe || esAdmin;
  const puedeGestionar = esJefe || esAdmin;
  const puedeCrearUsuarios = esJefe;
  const puedeUsarMesas = esJefe || esAdmin || esMesero || esCaja;
  const puedeCobrar = esJefe || esAdmin || esCaja;
  const puedeAbrirCerrarCaja = esJefe || esAdmin || esCaja;
  const puedeEditarMenu = esJefe || esAdmin;
  const cajaAbierta = Boolean(cajaActual?.abierta);

  const mesaSeleccionada = useMemo(() => mesas.find((mesa) => mesa.id === mesaId) || null, [mesaId, mesas]);
  const cuentaSolicitada = mesaSeleccionada?.estado === "Cuenta solicitada";
  const tieneItemsImpresos = Boolean(mesaSeleccionada?.orden.some((item) => item.enviadoComanda));
  const puedeAgregarOrdenActual = Boolean(mesaSeleccionada && (esJefe || esAdmin || esMesero || esCaja) && (mesaSeleccionada.orden.length === 0 || mesaSeleccionada.orden.some((item) => !item.pagado)));
  const puedeEditarOrdenActual = puedeAgregarOrdenActual;
  const puedeMarcarLlevarOrden = Boolean(mesaSeleccionada && puedeUsarMesas && (mesaSeleccionada.orden.length === 0 || mesaSeleccionada.orden.some((item) => !item.pagado)));
  const puedeMarcarLlevarItem = (item: ItemOrden) => puedeUsarMesas && !item.pagado;
  const puedeEditarItem = (item: ItemOrden) => puedeEditarOrdenActual && !item.enviadoComanda && !item.pagado;

  const itemsCobroActual = useMemo(() => {
    if (!mesaSeleccionada) return [];
    return mesaSeleccionada.orden.filter((item) => {
      if (item.pagado) return false;
      if (!mesaSeleccionada.cuentaDividida) return true;
      return itemsPagoSeleccionados.includes(item.uid);
    });
  }, [itemsPagoSeleccionados, mesaSeleccionada]);

  const totalesMesa = calcularTotales(mesaSeleccionada?.orden.filter((item) => !item.pagado) || []);
  const totalesCobro = calcularTotales(itemsCobroActual);
  const pagoUsaEfectivo = metodoPago === "Efectivo" || metodoPago === "Mixto";
  const vueltoActual = pagoUsaEfectivo ? Math.max(0, montoRecibido - totalesCobro.total) : 0;
  const totalVendido = ventas.reduce((acc, venta) => acc + venta.total, 0);
  const unidadesVendidas = ventas.reduce((acc, venta) => acc + venta.items.reduce((s, item) => s + item.cantidad, 0), 0);
  const productoMasVendido = useMemo(() => {
    const conteo = contarProductosVendidos(ventas);
    const mayor = Object.entries(conteo).sort((a, b) => b[1] - a[1])[0];
    return mayor ? `${mayor[0]} (${mayor[1]})` : "Sin ventas";
  }, [ventas]);

  const productosVendidosTurno = useMemo(() => contarProductosVendidos(ventas), [ventas]);
  const efectivoVentasTurno = useMemo(
    () => ventas.filter((v) => v.metodoPago === "Efectivo" || v.metodoPago === "Mixto").reduce((acc, v) => acc + v.total, 0),
    [ventas]
  );
  const totalSalidasTurno = useMemo(() => salidasDinero.reduce((acc, salida) => acc + salida.monto, 0), [salidasDinero]);
  const efectivoEsperadoTurno = (cajaActual?.montoApertura || 0) + efectivoVentasTurno - totalSalidasTurno;

  useEffect(() => localStorage.setItem("gato_usuarios", JSON.stringify(usuarios)), [usuarios]);
  useEffect(() => localStorage.setItem("gato_productos", JSON.stringify(productos)), [productos]);
  useEffect(() => localStorage.setItem("gato_mesas", JSON.stringify(mesas)), [mesas]);
  useEffect(() => localStorage.setItem("gato_ventas", JSON.stringify(ventas)), [ventas]);
  useEffect(() => localStorage.setItem("gato_salidas", JSON.stringify(salidasDinero)), [salidasDinero]);
  useEffect(() => localStorage.setItem("gato_movimientos", JSON.stringify(movimientosCaja)), [movimientosCaja]);
  useEffect(() => localStorage.setItem("gato_cierres", JSON.stringify(cierresCaja)), [cierresCaja]);
  useEffect(() => {
    if (cajaActual) localStorage.setItem("gato_caja_actual", JSON.stringify(cajaActual));
    else localStorage.removeItem("gato_caja_actual");
  }, [cajaActual]);

  useEffect(() => {
    setItemsPagoSeleccionados([]);
    setMontoRecibido(0);
  }, [mesaId]);

  useEffect(() => {
    if (!usuarioActual) return;
    setVista("mesas");
  }, [usuarioActual]);

  const iniciarSesion = () => {
    const usuario = usuarios.find(
      (u) => u.usuario.toLowerCase() === usuarioLogin.trim().toLowerCase() && u.password === passwordLogin
    );
    if (!usuario) {
      setErrorLogin("Usuario o contraseña incorrectos");
      return;
    }
    const usuarioNormalizado = prepararUsuarioConRoles(usuario);
    setUsuarioActual(usuarioNormalizado);
    setRol(usuarioNormalizado.rol as Rol);
    localStorage.setItem("gato_usuario_actual", JSON.stringify(usuarioNormalizado));
    localStorage.setItem("gato_rol", JSON.stringify(usuarioNormalizado.rol));
    setUsuarioLogin("");
    setPasswordLogin("");
    setErrorLogin("");
  };

  const cerrarSesion = () => {
    localStorage.removeItem("gato_usuario_actual");
    localStorage.removeItem("gato_rol");
    setUsuarioActual(null);
    setRol(null);
    setMesaId(null);
  };

  const actualizarMesa = (mesaActualizada: Mesa) => {
    const tipoOrden = mesaActualizada.orden.length
      ? inferirTipoOrden(mesaActualizada.orden)
      : mesaActualizada.esParaLlevar || mesaActualizada.tipoOrden === "LLEVAR"
        ? "LLEVAR"
        : "LOCAL";
    setMesas((prev) => prev.map((mesa) => (mesa.id === mesaActualizada.id ? { ...mesaActualizada, tipoOrden } : mesa)));
  };

  const abrirMesa = (mesa: Mesa) => {
    if (mesa.estado === "Libre" && !mesa.fechaApertura) {
      const cliente = prompt("Nombre del cliente", mesa.esParaLlevar ? "Cliente para llevar" : "Cliente contado");
      if (!cliente?.trim()) return;
      actualizarMesa({
        ...mesa,
        estado: "Ocupada",
        cliente: cliente.trim(),
        invitados: 1,
        fechaApertura: new Date().toLocaleString("es-CR"),
      });
    }
    setMesaId(mesa.id);
  };

  const crearPedidoLlevar = () => {
    const cliente = prompt("¿A nombre de quién va el pedido para llevar?");
    if (!cliente?.trim()) return;
    const cantidadLlevar = mesas.filter((mesa) => mesa.esParaLlevar).length + 1;
    const nuevaMesa: Mesa = {
      id: -Date.now(),
      nombre: `LLEVAR ${cantidadLlevar}`,
      estado: "Ocupada",
      orden: [],
      cliente: cliente.trim(),
      invitados: 1,
      tipoOrden: "LLEVAR",
      fechaApertura: new Date().toLocaleString("es-CR"),
      esParaLlevar: true,
      cuentaDividida: false,
    };
    setMesas((prev) => [nuevaMesa, ...prev]);
    setMesaId(nuevaMesa.id);
  };

  const agregarMesa = () => {
    const nombre = prompt("Nombre o número de mesa", `Mesa ${mesas.filter((m) => m.id > 0).length + 1}`);
    if (!nombre?.trim()) return;
    const maxId = Math.max(0, ...mesas.filter((m) => m.id > 0).map((m) => m.id));
    setMesas((prev) => [
      ...prev,
      {
        id: maxId + 1,
        nombre: nombre.trim(),
        estado: "Libre",
        orden: [],
        cliente: "",
        invitados: 1,
        tipoOrden: "LOCAL",
      },
    ]);
  };

  const quitarMesa = (mesa: Mesa) => {
    if (mesa.estado !== "Libre" || mesa.orden.length > 0) {
      alert("Solo se pueden quitar mesas libres y sin orden.");
      return;
    }
    if (!confirm(`¿Quitar ${mesa.nombre}?`)) return;
    setMesas((prev) => prev.filter((m) => m.id !== mesa.id));
  };

  const agregarProductoOrden = (producto: Producto) => {
    if (!mesaSeleccionada) return;
    if (!puedeAgregarOrdenActual) {
      alert("Esta orden ya está pagada o no puede recibir productos.");
      return;
    }
    const consumo: TipoConsumo = mesaSeleccionada.esParaLlevar || mesaSeleccionada.tipoOrden === "LLEVAR" ? "LLEVAR" : "LOCAL";
    const orden = [...mesaSeleccionada.orden];
    const itemExistenteNuevo = orden.find((item) =>
      !item.enviadoComanda &&
      !item.pagado &&
      item.id === producto.id &&
      item.consumo === consumo &&
      !item.nota.trim() &&
      item.sinIngredientes.length === 0 &&
      item.extras.length === 0
    );

    if (itemExistenteNuevo) {
      const ordenActualizada = orden.map((item) =>
        item.uid === itemExistenteNuevo.uid ? { ...item, cantidad: item.cantidad + 1 } : item
      );
      actualizarMesa({ ...mesaSeleccionada, estado: "Ocupada", orden: ordenActualizada });
      return;
    }

    actualizarMesa({ ...mesaSeleccionada, estado: "Ocupada", orden: [...orden, crearItem(producto, consumo)] });
  };

  const cambiarCantidad = (uid: string, cambio: number) => {
    if (!mesaSeleccionada || !puedeEditarOrdenActual) return;
    const itemActual = mesaSeleccionada.orden.find((item) => item.uid === uid);
    if (!itemActual || itemActual.enviadoComanda || itemActual.pagado) {
      alert("Este producto ya fue impreso en comanda. No se puede modificar; agregá una línea nueva si ocupás más.");
      return;
    }
    const orden = mesaSeleccionada.orden
      .map((item) => (item.uid === uid ? { ...item, cantidad: item.cantidad + cambio } : item))
      .filter((item) => item.cantidad > 0);
    actualizarMesa({ ...mesaSeleccionada, estado: orden.length ? "Ocupada" : "Libre", orden });
  };

  const eliminarItem = (uid: string) => {
    if (!mesaSeleccionada || !puedeEditarOrdenActual) return;
    const itemActual = mesaSeleccionada.orden.find((item) => item.uid === uid);
    if (!itemActual) return;
    if (itemActual.enviadoComanda || itemActual.pagado) {
      alert("Este producto ya fue impreso en comanda/factura. No se puede eliminar.");
      return;
    }
    const orden = mesaSeleccionada.orden.filter((item) => item.uid !== uid);
    actualizarMesa({ ...mesaSeleccionada, estado: orden.length ? "Ocupada" : "Libre", orden });
  };

  const actualizarItem = (uid: string, cambios: Partial<ItemOrden>) => {
    if (!mesaSeleccionada || !puedeEditarOrdenActual) return;
    const itemActual = mesaSeleccionada.orden.find((item) => item.uid === uid);
    if (!itemActual || itemActual.enviadoComanda || itemActual.pagado) return;
    actualizarMesa({ ...mesaSeleccionada, orden: mesaSeleccionada.orden.map((item) => (item.uid === uid ? { ...item, ...cambios } : item)) });
  };

  const toggleIngrediente = (item: ItemOrden, ingrediente: string) => {
    const sinIngredientes = item.sinIngredientes.includes(ingrediente)
      ? item.sinIngredientes.filter((i) => i !== ingrediente)
      : [...item.sinIngredientes, ingrediente];
    actualizarItem(item.uid, { sinIngredientes });
  };

  const toggleExtra = (item: ItemOrden, extra: Extra) => {
    const existe = item.extras.some((e) => e.nombre === extra.nombre);
    const extras = existe ? item.extras.filter((e) => e.nombre !== extra.nombre) : [...item.extras, extra];
    actualizarItem(item.uid, { extras });
  };

  const cambiarConsumoItem = (uid: string, consumo: TipoConsumo) => {
    if (!mesaSeleccionada || !puedeUsarMesas) return;
    const itemActual = mesaSeleccionada.orden.find((item) => item.uid === uid);
    if (!itemActual || itemActual.pagado) {
      alert("Este producto ya está pagado. No se puede cambiar entre local/llevar.");
      return;
    }
    actualizarMesa({
      ...mesaSeleccionada,
      orden: mesaSeleccionada.orden.map((item) => (item.uid === uid ? { ...item, consumo } : item)),
    });
  };

  const cambiarConsumoOrden = (consumo: TipoConsumo) => {
    if (!mesaSeleccionada || !puedeUsarMesas) return;
    const itemsNoPagados = mesaSeleccionada.orden.filter((item) => !item.pagado);
    if (mesaSeleccionada.orden.length > 0 && itemsNoPagados.length === 0) {
      alert("Esta orden ya está pagada. No se puede cambiar entre local/llevar.");
      return;
    }
    actualizarMesa({
      ...mesaSeleccionada,
      tipoOrden: consumo,
      esParaLlevar: consumo === "LLEVAR",
      orden: mesaSeleccionada.orden.map((item) =>
        item.pagado ? item : { ...item, consumo }
      ),
    });
  };

  const enviarComanda = () => {
    if (!mesaSeleccionada || !mesaSeleccionada.orden.length) return;
    const itemsNuevos = mesaSeleccionada.orden.filter((item) => !item.enviadoComanda);
    if (!itemsNuevos.length) {
      alert("No hay productos nuevos para enviar a comanda.");
      return;
    }
    const mesaActualizada = { ...mesaSeleccionada, orden: mesaSeleccionada.orden.map((item) => ({ ...item, enviadoComanda: true })) };
    actualizarMesa(mesaActualizada);
    const ticketComanda: Ticket = { tipo: "comanda", mesa: mesaActualizada, items: itemsNuevos, usuario: usuarioActual?.nombre || rol || "Usuario", fecha: new Date().toLocaleString("es-CR") };
    void imprimirTicket(ticketComanda);
  };

  const solicitarCuenta = () => {
    if (!mesaSeleccionada || !mesaSeleccionada.orden.length) return;
    actualizarMesa({ ...mesaSeleccionada, estado: "Cuenta solicitada" });
    setItemsPagoSeleccionados([]);
    setMontoRecibido(0);
  };

  const toggleCuentaDividida = () => {
    if (!mesaSeleccionada) return;
    actualizarMesa({ ...mesaSeleccionada, cuentaDividida: !mesaSeleccionada.cuentaDividida });
    setItemsPagoSeleccionados([]);
  };

  const toggleItemPago = (uid: string) => {
    setItemsPagoSeleccionados((prev) => (prev.includes(uid) ? prev.filter((id) => id !== uid) : [...prev, uid]));
  };

  const cobrar = () => {
    if (!mesaSeleccionada || !itemsCobroActual.length) return;
    if (!cajaAbierta) {
      alert("Primero debés abrir caja.");
      return;
    }
    if (pagoUsaEfectivo && montoRecibido < totalesCobro.total) {
      alert("El monto recibido es menor al total.");
      return;
    }
    const recibidoFinal = pagoUsaEfectivo ? montoRecibido : totalesCobro.total;
    const vueltoFinal = pagoUsaEfectivo ? Math.max(0, montoRecibido - totalesCobro.total) : 0;
    const venta: Venta = {
      id: Date.now(),
      cuenta: Date.now() % 100000,
      fechaApertura: mesaSeleccionada.fechaApertura || new Date().toLocaleString("es-CR"),
      fechaCierre: new Date().toLocaleString("es-CR"),
      mesa: mesaSeleccionada.nombre,
      cliente: mesaSeleccionada.cliente || "Cliente contado",
      invitados: mesaSeleccionada.invitados || 1,
      metodoPago,
      subtotal: totalesCobro.subtotal,
      servicio: totalesCobro.servicio,
      total: totalesCobro.total,
      montoRecibido: recibidoFinal,
      vuelto: vueltoFinal,
      items: itemsCobroActual.map((item) => ({ ...item, pagado: true })),
      usuario: usuarioActual?.nombre || rol || "Usuario",
    };
    const movimiento: MovimientoCaja = {
      id: venta.id,
      fecha: venta.fechaCierre,
      tipo: "VENTA",
      descripcion: `Venta factura #${venta.cuenta} · ${venta.mesa} · ${venta.cliente} · ${venta.items.map((item) => `${item.cantidad}x ${item.nombre}`).join(", ")}`,
      monto: venta.total,
      metodoPago: venta.metodoPago,
      cuenta: venta.cuenta,
      mesa: venta.mesa,
      usuario: venta.usuario,
      items: venta.items.map((item) => ({ nombre: item.nombre, cantidad: item.cantidad, total: precioLinea(item), consumo: item.consumo })),
    };
    const ids = new Set(itemsCobroActual.map((item) => item.uid));
    const ordenActualizada = mesaSeleccionada.orden.map((item) => (ids.has(item.uid) ? { ...item, pagado: true } : item));
    const todoPagado = ordenActualizada.every((item) => item.pagado);
    setVentas((prev) => [venta, ...prev]);
    setMovimientosCaja((prev) => [movimiento, ...prev]);
    const ticketFactura: Ticket = { tipo: "factura", venta };
    void imprimirTicket(ticketFactura);
    setTimeout(() => {
        setMesas((prev) =>
          prev
            .map((mesa) => {
              if (mesa.id !== mesaSeleccionada.id) return mesa;
              if (todoPagado) {
                if (mesa.esParaLlevar) return null;
                return { ...mesa, estado: "Libre", orden: [], cliente: "", invitados: 1, fechaApertura: undefined, tipoOrden: "LOCAL", cuentaDividida: false };
              }
              return { ...mesa, estado: "Ocupada", orden: ordenActualizada, cuentaDividida: false };
            })
            .filter(Boolean) as Mesa[]
        );
        setMesaId(todoPagado ? null : mesaSeleccionada.id);
        setMetodoPago("Efectivo");
        setMontoRecibido(0);
        setItemsPagoSeleccionados([]);
    }, 700);
  };

  const reimprimirFactura = (venta: Venta) => {
    const ticketFactura: Ticket = { tipo: "factura", venta };
    void imprimirTicket(ticketFactura);
  };

  const imprimirCierre = (cierre: CierreCaja) => {
    if (!puedeVerDetalleCierre(cierre)) {
      alert("Solo Admin/Jefe puede imprimir historial completo. Caja solo puede imprimir el último cierre mientras la caja esté cerrada.");
      return;
    }
    const ticketCierre: Ticket = { tipo: "cierre", cierre };
    void imprimirTicket(ticketCierre);
  };

  const abrirCaja = () => {
    if (!puedeAbrirCerrarCaja) {
      alert("Solo Caja, Admin o Jefe puede abrir caja.");
      return;
    }

    const texto = window.prompt("¿Con cuánto efectivo se abre la caja? Este monto es fondo para vuelto, no es ganancia.", "0");
    if (texto === null) return;

    const monto = Number(texto);
    if (Number.isNaN(monto) || monto < 0) {
      alert("Monto inválido.");
      return;
    }

    const fecha = new Date().toLocaleString("es-CR");
    const usuario = usuarioActual?.nombre || rol || "Usuario";
    setCierreDetalle(null);
    setCajaActual({ abierta: true, montoApertura: monto, fechaApertura: fecha, usuario });
    setMovimientosCaja((prev) => [{
      id: Date.now(),
      fecha,
      tipo: "APERTURA",
      descripcion: `Apertura de caja con fondo para vuelto. Este monto no cuenta como venta ni ganancia.`,
      monto,
      metodoPago: "N/A",
      usuario,
    }, ...prev]);
  };

  const registrarSalida = () => {
    if (!puedeVerCajaDetallada) {
      alert("Solo Admin o Jefe puede registrar salidas de dinero.");
      return;
    }
    if (!cajaAbierta) {
      alert("Primero abrí caja.");
      return;
    }
    const motivo = prompt("Motivo o descripción exacta de la salida de dinero");
    if (!motivo?.trim()) return;
    const texto = prompt("Monto de salida");
    if (texto === null) return;
    const monto = Number(texto);
    if (Number.isNaN(monto) || monto <= 0) {
      alert("Monto inválido.");
      return;
    }
    const fecha = new Date().toLocaleString("es-CR");
    const usuario = usuarioActual?.nombre || rol || "Usuario";
    const salida: SalidaDinero = { id: Date.now(), fecha, monto, motivo: motivo.trim(), usuario };
    setSalidasDinero((prev) => [salida, ...prev]);
    setMovimientosCaja((prev) => [{
      id: salida.id,
      fecha,
      tipo: "SALIDA",
      descripcion: `Salida de efectivo: ${motivo.trim()}. Se rebaja del efectivo físico disponible en caja, pero no se resta del total vendido/ganado.`,
      monto,
      metodoPago: "Efectivo",
      usuario,
    }, ...prev]);
  };

  const cerrarCaja = () => {
    if (!puedeAbrirCerrarCaja) {
      alert("Solo Caja, Admin o Jefe puede cerrar caja.");
      return;
    }
    if (!cajaAbierta) {
      alert("No hay caja abierta.");
      return;
    }
    const texto = prompt("¿Cuánto efectivo real hay en caja?");
    if (texto === null) return;
    const efectivoReportado = Number(texto);
    if (Number.isNaN(efectivoReportado) || efectivoReportado < 0) {
      alert("Monto inválido.");
      return;
    }
    const ventasTurno = [...ventas];
    const salidasTurno = [...salidasDinero];
    const efectivoVentas = ventasTurno.filter((v) => v.metodoPago === "Efectivo" || v.metodoPago === "Mixto").reduce((acc, v) => acc + v.total, 0);
    const tarjeta = ventasTurno.filter((v) => v.metodoPago === "Tarjeta").reduce((acc, v) => acc + v.total, 0);
    const sinpe = ventasTurno.filter((v) => v.metodoPago === "SINPE").reduce((acc, v) => acc + v.total, 0);
    const mixto = ventasTurno.filter((v) => v.metodoPago === "Mixto").reduce((acc, v) => acc + v.total, 0);
    const salidas = salidasTurno.reduce((acc, salida) => acc + salida.monto, 0);
    const fondoInicial = cajaActual?.montoApertura || 0;
    const efectivoEsperado = fondoInicial + efectivoVentas - salidas;
    const productosVendidos = contarProductosVendidos(ventasTurno);
    const fecha = new Date().toLocaleString("es-CR");
    const usuario = usuarioActual?.nombre || rol || "Usuario";
    const cierreMovimiento: MovimientoCaja = {
      id: Date.now(),
      fecha,
      tipo: "CIERRE",
      descripcion: `Cierre de turno. Efectivo contado ${formatoCRC(efectivoReportado)}. Efectivo esperado ${formatoCRC(efectivoEsperado)}. Diferencia ${formatoCRC(efectivoReportado - efectivoEsperado)}.`,
      monto: efectivoReportado,
      metodoPago: "N/A",
      usuario,
    };
    const cierre: CierreCaja = {
      id: Date.now(),
      fecha,
      usuario,
      montoApertura: fondoInicial,
      efectivoVentas,
      tarjeta,
      sinpe,
      mixto,
      salidas,
      efectivoEsperado,
      efectivoReportado,
      diferencia: efectivoReportado - efectivoEsperado,
      totalGeneral: ventasTurno.reduce((acc, venta) => acc + venta.total, 0),
      cantidadVentas: ventasTurno.length,
      productosVendidos,
      movimientos: [cierreMovimiento, ...movimientosCaja],
      ventasDetalle: ventasTurno,
      salidasDetalle: salidasTurno,
    };
    setCierresCaja((prev) => [cierre, ...prev]);
    setVentas([]);
    setSalidasDinero([]);
    setMovimientosCaja([]);
    setCajaActual(null);
    setCierreDetalle(cierre);
    if (puedeVerCajaDetallada) {
      alert("Cierre de caja registrado. Revisá el detalle completo del cierre.");
    } else {
      alert("Cierre de caja registrado. Podés ver el detalle de este último cierre hasta que abras caja de nuevo.");
    }
  };

  const crearProducto = () => {
    if (!nuevoProducto.nombre.trim() || nuevoProducto.precio <= 0) {
      alert("Nombre y precio son obligatorios.");
      return;
    }
    setProductos((prev) => [...prev, { ...nuevoProducto, id: Date.now(), ingredientes: nuevoProducto.ingredientes || [] }]);
    setNuevoProducto({ id: 0, categoria: "Tacos", nombre: "", descripcion: "", precio: 0, ingredientes: [] });
  };

  const actualizarProducto = (id: number, cambios: Partial<Producto>) => {
    setProductos((prev) => prev.map((producto) => (producto.id === id ? { ...producto, ...cambios } : producto)));
  };

  const eliminarProductoAdmin = (id: number) => {
    if (!confirm("¿Eliminar producto del menú?")) return;
    setProductos((prev) => prev.filter((producto) => producto.id !== id));
  };

  const restaurarMenuGato = () => {
    if (!confirm("¿Restaurar el menú oficial de Gato Calavera?")) return;
    setProductos(productosGato);
  };

  const crearUsuario = () => {
    if (!puedeCrearUsuarios) return;
    if (!nuevoUsuario.usuario.trim() || !nuevoUsuario.password.trim()) {
      alert("Usuario y contraseña son obligatorios.");
      return;
    }
    const rolesNuevoUsuario = normalizarRolesUsuario(nuevoUsuario);
    if (!rolesNuevoUsuario.length) {
      alert("Seleccioná al menos un rol para el usuario.");
      return;
    }
    const existe = usuarios.some((u) => u.usuario.toLowerCase() === nuevoUsuario.usuario.toLowerCase());
    if (existe) {
      alert("Ese usuario ya existe.");
      return;
    }
    const usuarioCreado = prepararUsuarioConRoles({ ...nuevoUsuario, nombre: nuevoUsuario.nombre.trim() || nuevoUsuario.usuario.trim() });
    setUsuarios((prev) => [...prev, usuarioCreado]);
    setNuevoUsuario({ usuario: "", password: "", nombre: "", rol: "Mesero", roles: ["Mesero"] });
  };

  const actualizarUsuario = (usuario: string, cambios: Partial<Usuario>) => {
    if (!puedeCrearUsuarios) return;
    setUsuarios((prev) => prev.map((u) => (u.usuario === usuario ? prepararUsuarioConRoles({ ...u, ...cambios }) : u)));
  };

  const cambiarRolNuevoUsuario = (rolCambio: Rol) => {
    const rolesActualesNuevo = normalizarRolesUsuario(nuevoUsuario);
    const rolesSiguientes = rolesActualesNuevo.includes(rolCambio)
      ? rolesActualesNuevo.filter((r) => r !== rolCambio)
      : [...rolesActualesNuevo, rolCambio];
    const rolesFinales = rolesSiguientes.length ? rolesSiguientes : (["Mesero"] as Rol[]);
    setNuevoUsuario({ ...nuevoUsuario, roles: rolesFinales, rol: rolPrincipalDe(rolesFinales) });
  };

  const cambiarRolUsuarioExistente = (usuario: Usuario, rolCambio: Rol) => {
    if (!puedeCrearUsuarios) return;
    const rolesActualesUsuario = normalizarRolesUsuario(usuario);
    const rolesSiguientes = rolesActualesUsuario.includes(rolCambio)
      ? rolesActualesUsuario.filter((r) => r !== rolCambio)
      : [...rolesActualesUsuario, rolCambio];
    const rolesFinales = rolesSiguientes.length ? rolesSiguientes : (["Mesero"] as Rol[]);
    actualizarUsuario(usuario.usuario, { roles: rolesFinales, rol: rolPrincipalDe(rolesFinales) });
  };

  const eliminarUsuario = (usuario: string) => {
    if (!puedeCrearUsuarios) return;
    if (usuario === "jefe") {
      alert("No se puede eliminar el usuario jefe principal.");
      return;
    }
    if (!confirm("¿Eliminar usuario?")) return;
    setUsuarios((prev) => prev.filter((u) => u.usuario !== usuario));
  };

  const limpiarSistema = () => {
    if (!esJefe) return;
    if (!confirm("¿Reiniciar mesas, ventas, caja y cierres?")) return;
    setMesas(crearMesasIniciales());
    setVentas([]);
    setSalidasDinero([]);
    setMovimientosCaja([]);
    setCierresCaja([]);
    setCajaActual(null);
    setMesaId(null);
  };

  const agregarProductoQR = (producto: Producto) => {
    setOrdenQR((prev) => [...prev, crearItem(producto, "LOCAL")]);
  };

  const enviarPedidoQR = () => {
    const mesaNumero = Number(mesaQR);
    if (!mesaNumero || !ordenQR.length) {
      alert("Agregá al menos un producto.");
      return;
    }
    const cliente = prompt("¿A nombre de quién está el pedido?", "Cliente QR") || "Cliente QR";
    setMesas((prev) =>
      prev.map((mesa) =>
        mesa.id === mesaNumero
          ? {
              ...mesa,
              estado: "Ocupada",
              cliente: mesa.cliente || cliente,
              invitados: mesa.invitados || 1,
              fechaApertura: mesa.fechaApertura || new Date().toLocaleString("es-CR"),
              orden: [...mesa.orden, ...ordenQR.map((item) => ({ ...item, nota: notaQR, enviadoComanda: true }))],
            }
          : mesa
      )
    );
    alert("Pedido enviado correctamente.");
    setOrdenQR([]);
    setNotaQR("");
  };


  const limpiarTextoTicket = (texto: string) =>
    texto
      .normalize("NFD")
      .replace(/[\u0300-\u036f]/g, "")
      .replace(/₡/g, "CRC ")
      .replace(/[“”]/g, '"')
      .replace(/[‘’]/g, "'");

  const centrarTicket = (texto: string, ancho = 42) => {
    const valor = limpiarTextoTicket(texto).slice(0, ancho);
    const espacios = Math.max(0, Math.floor((ancho - valor.length) / 2));
    return `${" ".repeat(espacios)}${valor}`;
  };

  const lineaTicket = (izquierda: string, derecha = "", ancho = 42) => {
    const izq = limpiarTextoTicket(izquierda).slice(0, ancho);
    const der = limpiarTextoTicket(derecha).slice(0, Math.max(0, ancho - 2));
    const espacios = Math.max(1, ancho - izq.length - der.length);
    return `${izq}${" ".repeat(espacios)}${der}`;
  };

  const formatoNumeroTicket = (valor: number) => {
    const numero = Number(valor || 0);
    return numero.toLocaleString("en-US", {
      minimumFractionDigits: 2,
      maximumFractionDigits: 2,
    });
  };

  const partirFechaHoraTicket = (valor?: string) => {
    const limpio = limpiarTextoTicket(valor || "").trim();
    const match = limpio.match(/^(\d{1,2}\/\d{1,2}\/\d{2,4}),?\s*(.*)$/);
    return {
      fecha: match?.[1] || limpio,
      hora: (match?.[2] || "").trim(),
    };
  };

  const recortarTicket = (texto: string, largo = 34) => {
    const limpio = limpiarTextoTicket(texto || "");
    return limpio.length > largo ? `${limpio.slice(0, largo - 3)}...` : limpio;
  };

  const ticketComoTexto = (ticket: Ticket) => {
    const sep = "------------------------------------------";
    const lineas: string[] = [];
    const add = (valor = "") => lineas.push(limpiarTextoTicket(valor));

    const itemFactura = (item: ItemOrden) => {
      const nombre = recortarTicket(item.nombre, 28);
      const total = formatoNumeroTicket(precioLinea(item));
      add(lineaTicket(nombre, total));
      if (item.cantidad > 1) add(`  ${item.cantidad} x ${formatoNumeroTicket(item.precio + item.extras.reduce((acc, extra) => acc + extra.precio, 0))}`);
      if (item.sinIngredientes.length) add(`  SIN: ${recortarTicket(item.sinIngredientes.join(", "), 34)}`);
      if (item.extras.length) add(`  EXTRA: ${recortarTicket(item.extras.map((e) => e.nombre).join(", "), 32)}`);
      if (item.nota.trim()) add(`  NOTA: ${recortarTicket(item.nota.trim(), 33)}`);
    };

    const itemComanda = (item: ItemOrden) => {
      add(`${String(item.cantidad).padEnd(5, " ")} ${recortarTicket(item.nombre, 34)}`);
      if (item.consumo === "LLEVAR") add("      PARA LLEVAR");
      if (item.sinIngredientes.length) add(`      SIN: ${recortarTicket(item.sinIngredientes.join(", "), 31)}`);
      if (item.extras.length) add(`      EXTRA: ${recortarTicket(item.extras.map((e) => e.nombre).join(", "), 29)}`);
      if (item.nota.trim()) add(`      NOTA: ${recortarTicket(item.nota.trim(), 30)}`);
    };

    if (ticket.tipo === "comanda") {
      const fechaTicket = partirFechaHoraTicket(ticket.fecha);
      add(centrarTicket("COMANDA"));
      add("");
      add(centrarTicket(fechaTicket.fecha || new Date().toLocaleDateString("es-CR")));
      add("");
      add(centrarTicket(ticket.mesa.tipoOrden === "LLEVAR" ? "Llevar" : "Aqui"));
      add("");
      add(`A nombre de: ${ticket.mesa.cliente || "Cliente"}`);
      add(`Salonero: ${ticket.usuario}`);
      add(`Hora comanda: ${fechaTicket.hora || ticket.fecha}`);
      add(`Mesa: ${ticket.mesa.tipoOrden === "LLEVAR" ? "LLEVAR" : ticket.mesa.nombre}`);
      add("Pacayas");
      add("");
      add(sep);
      add("Cant. Descripcion");
      add(sep);
      ticket.items.forEach(itemComanda);
      add(sep);
      add(centrarTicket("******ULTIMA LINEA******"));
      return `${lineas.join("\n")}\n\n\n`;
    }

    if (ticket.tipo === "cierre") {
      const cierre = ticket.cierre;
      add(centrarTicket("GATO CALAVERA"));
      add(centrarTicket("CIERRE TURNO"));
      add(sep);
      add(cierre.fecha);
      add(`Usuario: ${cierre.usuario}`);
      add(sep);
      add(lineaTicket("Fondo vuelto", formatoNumeroTicket(cierre.montoApertura)));
      add(lineaTicket("Total vendido", formatoNumeroTicket(cierre.totalGeneral)));
      add(lineaTicket("Efectivo ventas", formatoNumeroTicket(cierre.efectivoVentas)));
      add(lineaTicket("Tarjeta", formatoNumeroTicket(cierre.tarjeta)));
      add(lineaTicket("SINPE", formatoNumeroTicket(cierre.sinpe)));
      add(lineaTicket("Salidas", formatoNumeroTicket(cierre.salidas)));
      add(lineaTicket("Esperado caja", formatoNumeroTicket(cierre.efectivoEsperado)));
      add(lineaTicket("Contado", formatoNumeroTicket(cierre.efectivoReportado)));
      add(lineaTicket("Diferencia", formatoNumeroTicket(cierre.diferencia)));
      add(sep);
      add("PRODUCTOS");
      Object.entries(cierre.productosVendidos || {}).forEach(([producto, cantidad]) => add(`${producto}: ${cantidad}`));
      add(sep);
      add(centrarTicket("FIN CIERRE"));
      return `${lineas.join("\n")}\n\n\n`;
    }

    const venta = ticket.venta;
    const apertura = partirFechaHoraTicket(venta.fechaApertura);
    const cierre = partirFechaHoraTicket(venta.fechaCierre);
    add(centrarTicket("Gato Calavera Pacayas"));
    add(centrarTicket("Alessandro Rubi Silesky"));
    add(centrarTicket("ID No: 1-1835-0862"));
    add(centrarTicket("alessandrorubi6@gmail.com"));
    add(centrarTicket("Telefono: 7229-3155"));
    add(centrarTicket("FACTURA"));
    add("");
    add(`Fecha apertura: ${[apertura.fecha, apertura.hora].filter(Boolean).join(" ")}`);
    add(`Fecha cierre:   ${[cierre.fecha, cierre.hora].filter(Boolean).join(" ")}`);
    add(lineaTicket(`Cuenta: ${venta.cuenta}`, `Mesa: ${venta.mesa}`));
    add(`Invitados: ${venta.invitados}`);
    add("ID Cliente:");
    add(`Nombre: ${venta.cliente || "Cliente Contado"}`);
    add(sep);
    add(lineaTicket("Descripcion", "Precio"));
    add(sep);
    venta.items.forEach(itemFactura);
    add(sep);
    add(lineaTicket("SubTotal:", formatoNumeroTicket(venta.subtotal)));
    if (venta.servicio > 0) add(lineaTicket("10% Servicio:", formatoNumeroTicket(venta.servicio)));
    add(lineaTicket("Total:", formatoNumeroTicket(venta.total)));
    if (venta.metodoPago === "Efectivo" || venta.metodoPago === "Mixto") {
      add(lineaTicket("Recibido:", formatoNumeroTicket(venta.montoRecibido)));
      add(lineaTicket("Vuelto:", formatoNumeroTicket(venta.vuelto)));
    }
    add("");
    add("Condicion de venta: Contado");
    add(`Metodo de pago: ${venta.metodoPago}`);
    add(sep);
    add("Moneda: CRC");
    add(sep);
    add(centrarTicket("Regimen de Tributacion Simplificada"));
    return `${lineas.join("\n")}\n\n\n`;
  };

  const payloadImpresion = (ticket: Ticket) => {
    const texto = ticketComoTexto(ticket);

    if (ticket.tipo === "comanda") {
      return {
        tipo: ticket.tipo,
        texto,
        mesa: ticket.mesa.tipoOrden === "LLEVAR" ? "LLEVAR" : ticket.mesa.nombre,
        cliente: ticket.mesa.cliente || "Cliente",
        usuario: ticket.usuario,
        fecha: ticket.fecha,
        productos: ticket.items.map((item) => ({
          nombre: item.nombre,
          cantidad: item.cantidad,
          notas: [
            item.sinIngredientes.length ? `SIN: ${item.sinIngredientes.join(", ")}` : "",
            item.extras.length ? `EXTRA: ${item.extras.map((extra) => extra.nombre).join(", ")}` : "",
            item.nota.trim(),
          ].filter(Boolean).join(" | "),
          llevar: item.consumo === "LLEVAR",
        })),
      };
    }

    if (ticket.tipo === "cierre") {
      return {
        tipo: ticket.tipo,
        texto,
        usuario: ticket.cierre.usuario,
        fecha: ticket.cierre.fecha,
        montoInicial: ticket.cierre.montoApertura,
        efectivo: ticket.cierre.efectivoVentas,
        tarjeta: ticket.cierre.tarjeta,
        sinpe: ticket.cierre.sinpe,
        salidas: ticket.cierre.salidas,
        total: ticket.cierre.totalGeneral,
        efectivoEsperado: ticket.cierre.efectivoEsperado,
        efectivoReportado: ticket.cierre.efectivoReportado,
        diferencia: ticket.cierre.diferencia,
      };
    }

    return {
      tipo: ticket.tipo,
      texto,
      mesa: ticket.venta.mesa,
      cliente: ticket.venta.cliente,
      cuenta: ticket.venta.cuenta,
      fecha: ticket.venta.fechaCierre,
      metodoPago: ticket.venta.metodoPago,
      productos: ticket.venta.items.map((item) => ({
        nombre: item.nombre,
        cantidad: item.cantidad,
        precio: item.precio + item.extras.reduce((acc, extra) => acc + extra.precio, 0),
        notas: item.nota,
        llevar: item.consumo === "LLEVAR",
      })),
      subtotal: ticket.venta.subtotal,
      servicio: ticket.venta.servicio,
      total: ticket.venta.total,
      efectivo: ticket.venta.metodoPago === "Efectivo" || ticket.venta.metodoPago === "Mixto" ? ticket.venta.montoRecibido : undefined,
      vuelto: ticket.venta.metodoPago === "Efectivo" || ticket.venta.metodoPago === "Mixto" ? ticket.venta.vuelto : undefined,
    };
  };

  const postImpresion = async (url: string, payload: unknown) => {
    const controller = new AbortController();
    const timer = window.setTimeout(() => controller.abort(), PRINT_REQUEST_TIMEOUT_MS);
    try {
      const respuesta = await fetch(url, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(payload),
        signal: controller.signal,
      });
      const data = await respuesta.json().catch(() => null);
      if (!respuesta.ok || data?.ok === false) throw new Error(data?.error || "Servicio de impresora no disponible");
      return data;
    } finally {
      window.clearTimeout(timer);
    }
  };

  const imprimirTicket = async (ticket: Ticket) => {
    setTicketActual(ticket);
    const payload = payloadImpresion(ticket);
    const rutas = [`${PRINT_SERVER_URL}/print/${ticket.tipo}`, `${PRINT_SERVER_URL}/print`];
    let ultimoError: unknown = null;

    for (const ruta of rutas) {
      try {
        await postImpresion(ruta, payload);
        setImpresoraOnline(true);
        setMensajeImpresora("Impresora local OK: TERMICA");
        return;
      } catch (error) {
        ultimoError = error;
      }
    }

    setImpresoraOnline(false);
    setMensajeImpresora("No se pudo imprimir. Servicio local desconectado.");
    console.error("Error imprimiendo ticket", ultimoError);
    alert("No se pudo imprimir. Revisá que la impresora TERMICA esté encendida y que el servicio local Gato Calavera esté instalado. Probá http://127.0.0.1:5055/health en Chrome.");
  };

  const probarImpresoraLocal = async () => {
    try {
      const controller = new AbortController();
      const timer = window.setTimeout(() => controller.abort(), PRINT_REQUEST_TIMEOUT_MS);
      const respuesta = await fetch(`${PRINT_SERVER_URL}/test-print`, { signal: controller.signal });
      window.clearTimeout(timer);
      const data = await respuesta.json().catch(() => null);
      if (!respuesta.ok || data?.ok === false) throw new Error(data?.error || "No se pudo imprimir prueba");
      setImpresoraOnline(true);
      setMensajeImpresora("Impresora local OK: TERMICA");
      alert("Prueba enviada a la impresora.");
    } catch {
      setImpresoraOnline(false);
      setMensajeImpresora("Impresora local desconectada.");
      alert("No se pudo imprimir la prueba. Revisá http://127.0.0.1:5055/health y que la impresora TERMICA esté encendida.");
    }
  };

  const imprimirQR = () => window.print();
  const baseMenuPublico = ((import.meta.env.VITE_MENU_PUBLIC_URL as string | undefined) || window.location.origin).replace(/\/$/, "");
  const rutaMenuPublico = window.location.pathname === "/" ? "" : window.location.pathname;
  const crearUrlMenuQR = (id: number) => `${baseMenuPublico}${rutaMenuPublico}?mesa=${id}&menu=1`;
  const copiarLinkQR = (id: number) => {
    const url = crearUrlMenuQR(id);
    navigator.clipboard.writeText(url);
    alert(`Link copiado para mesa ${id}`);
  };

  if (modoMenuQR && mesaQR) {
    const categorias = categoriasProducto.filter((categoria) => productos.some((p) => p.categoria === categoria));
    const totalQR = calcularTotales(ordenQR).total;
    return (
      <div className="qr-menu-page">
        <div className="menu-confetti" />
        <div className="menu-card-dark">
          <div className="menu-float menu-left">🌶️</div>
          <div className="menu-float menu-right">🌮</div>
          <div className="menu-head">
            <div className="skull">💀</div>
            <h1 className="menu-title">SPECIAL MENU</h1>
            <div className="sombrero">🌮</div>
            <p>Gato Calabera · MESA {mesaQR}</p>
            <span className="menu-label">MENÚ</span>
          </div>

          <div className="menu-columns">
            {categorias.map((categoria, index) => (
              <section key={categoria}>
                <h2 className={`cat-title cat-${index % 3}`}>{categoria === "Bebidas" ? "REFRESCO" : categoria}</h2>
                {productos
                  .filter((producto) => producto.categoria === categoria)
                  .map((producto) => (
                    <button key={producto.id} className="public-menu-item" onClick={() => agregarProductoQR(producto)}>
                      <span>
                        <strong>{producto.nombre}</strong>
                        <small>{producto.descripcion || "Preparado al momento · sabor de la casa"}</small>
                      </span>
                      <i />
                      <b>{formatoCRC(producto.precio)}</b>
                    </button>
                  ))}
              </section>
            ))}
          </div>

          

          <div className="menu-footer">🌵 🌶️ 🪅 🌮 🌵<h2>¡Buen provecho!</h2></div>
        </div>
      </div>
    );
  }

  if (!rol) {
    return (
      <div className="login-page">
        <div className="login-card">
          <img src={logoTicketDataUri} alt="Gato Calavera" />
          <h1>Gato Calavera POS</h1>
          <p>Inicio de sesión</p>
          <input value={usuarioLogin} onChange={(e) => setUsuarioLogin(e.target.value)} placeholder="Usuario" />
          <input
            type="password"
            value={passwordLogin}
            onChange={(e) => setPasswordLogin(e.target.value)}
            placeholder="Contraseña"
            onKeyDown={(e) => e.key === "Enter" && iniciarSesion()}
          />
          {errorLogin && <strong className="error-login">{errorLogin}</strong>}
          <button onClick={iniciarSesion}>Entrar</button>
          
        </div>
      </div>
    );
  }

  const ultimoCierre = cierresCaja[0];
  const fechaHoy = new Date().toLocaleDateString("es-CR");
  const ultimoCierreDelDia = cierresCaja.find((cierre) => (cierre.fecha || "").startsWith(fechaHoy));
  const ultimoCierreVisibleCaja = !cajaAbierta ? ultimoCierreDelDia : undefined;
  const puedeVerDetalleCierre = (cierre: CierreCaja) =>
    puedeVerCajaDetallada || (esCajaOperativa && !cajaAbierta && Boolean(ultimoCierreVisibleCaja) && cierre.id === ultimoCierreVisibleCaja?.id);

  return (
    <div className="app-shell">
      <aside className="sidebar no-print">
        <div>
          <div className="brand">
            <img src={logoTicketDataUri} alt="Gato Calavera" />
          </div>
          <nav className="side-menu">
            <button className={vista === "inicio" ? "active" : ""} onClick={() => setVista("inicio")}>🏠 Inicio</button>
            {puedeUsarMesas && <button className={vista === "mesas" ? "active" : ""} onClick={() => setVista("mesas")}>🪑 Mesas y órdenes</button>}
            {puedeCobrar && <button className={vista === "caja" ? "active" : ""} onClick={() => setVista("caja")}>💵 Caja / cierre</button>}
            {puedeCobrar && <button className={vista === "facturas" ? "active" : ""} onClick={() => setVista("facturas")}>🧾 Facturas</button>}
            {puedeEditarMenu && <button className={vista === "menu" ? "active" : ""} onClick={() => setVista("menu")}>🌮 Menú</button>}
            {puedeCrearUsuarios && <button className={vista === "usuarios" ? "active" : ""} onClick={() => setVista("usuarios")}>👥 Usuarios</button>}
            {puedeGestionar && <button className={vista === "qr" ? "active" : ""} onClick={() => setVista("qr")}>▦ QR mesas</button>}
          </nav>
        </div>
        <div className="sidebar-bottom">
          <div className="user-box"><b>{usuarioActual?.nombre}</b><span>{rolesTextoActual}</span></div>
          {esJefe && <button className="danger" onClick={limpiarSistema}>Reiniciar sistema</button>}
          <button className="danger" onClick={cerrarSesion}>Salir</button>
        </div>
      </aside>

      <main className="content">
        <header className="topbar no-print">
          <div>
            <h1>Gato Calavera Pacayas</h1>
            <p>Control del día, comandas, facturas y cierre de turno.</p>
          </div>
          <div className="top-pills">
            <span className={cajaAbierta ? "pill ok" : "pill warn"}>{cajaAbierta ? "Caja abierta" : "Caja cerrada"}</span>
            <button type="button" className={impresoraOnline ? "pill ok printer-pill" : "pill warn printer-pill"} onClick={() => verificarImpresoraLocal(true)} title={mensajeImpresora}>
              {impresoraOnline ? "🖨️ Impresora OK" : "🖨️ Impresora off"}
            </button>
            <span className="pill">{new Date().toLocaleDateString("es-CR")}</span>
            <span className="pill">Rol: {rolesTextoActual}</span>
          </div>
        </header>

        {vista === "inicio" && (
          <section className="page no-print">
            <>
              <div className="hero-card"><h1>Control del día</h1><p>Órdenes, comandas, facturas y cierre de turno en un solo lugar.</p></div>
              <div className="stats-grid">
                <Stat title="Ventas hoy" value={formatoCRC(totalVendido)} />
                <Stat title="Facturas" value={ventas.length.toString()} />
                <Stat title="Mesas ocupadas" value={mesas.filter((m) => m.estado !== "Libre").length.toString()} />
                <Stat title="Producto top" value={productoMasVendido} />
              </div>
            </>
          </section>
        )}

        {vista === "mesas" && puedeUsarMesas && !mesaSeleccionada && (
          <section className="page no-print">
            <div className="page-title">
              <div><h1>Mesas y órdenes</h1><p>Local, para llevar y órdenes mixtas.</p></div>
              <div className="actions-row">
                <button onClick={crearPedidoLlevar} className="primary">+ Para llevar</button>
                {puedeGestionar && <button onClick={agregarMesa}>+ Agregar mesa</button>}
              </div>
            </div>
            <div className="tables-grid">
              {mesas.map((mesa) => (
                <div key={mesa.id} className={`mesa-card ${mesa.estado !== "Libre" ? "busy" : ""}`}>
                  <button onClick={() => abrirMesa(mesa)}>
                    <span>{mesa.esParaLlevar ? "🥡" : "🪑"}</span>
                    <h2>{mesa.nombre}</h2>
                    <p>{mesa.estado}</p>
                    {mesa.cliente && <small>A nombre de: {mesa.cliente}</small>}
                    {mesa.orden.length > 0 && <b>{formatoCRC(calcularTotales(mesa.orden.filter((item) => !item.pagado)).total)}</b>}
                  </button>
                  {puedeGestionar && !mesa.esParaLlevar && mesa.estado === "Libre" && <button className="remove-table" onClick={() => quitarMesa(mesa)}>Quitar</button>}
                </div>
              ))}
            </div>
          </section>
        )}

        {vista === "mesas" && puedeUsarMesas && mesaSeleccionada && (
          <section className="page order-page no-print">
            <button onClick={() => setMesaId(null)}>← Volver</button>
            <div className="order-head order-head-simple">
              <div>
                <h1>{mesaSeleccionada.nombre}</h1>
                <div className="quick-order-fields simple-client-field">
                  <label>Cliente
                    <input
                      value={mesaSeleccionada.cliente}
                      onChange={(e) => actualizarMesa({ ...mesaSeleccionada, cliente: e.target.value })}
                      placeholder="Nombre del cliente"
                    />
                  </label>
                </div>
              </div>
            </div>

            {tieneItemsImpresos && <div className="alert">Productos impresos quedan marcados como IMPRESO. No se eliminan ni se cambia cantidad/detalle, pero sí podés marcar Local/Llevar antes de cobrar.</div>}

            <div className="pos-order-workspace">
              {puedeEditarOrdenActual && (
                <div className="pos-products-panel">
                  <div className="category-card-tabs">
                    {categoriasProducto.map((categoria) => {
                      const cantidadCategoria = mesaSeleccionada.orden
                        .filter((item) => item.categoria === categoria && !item.pagado)
                        .reduce((acc, item) => acc + item.cantidad, 0);
                      return (
                        <button
                          key={categoria}
                          className={categoriaActiva === categoria ? "active" : ""}
                          onClick={() => setCategoriaActiva(categoria)}
                        >
                          <span>{categoria === "Tacos" ? "🌮" : categoria === "Hamburguesas" ? "🍔" : categoria === "Papas" ? "🍟" : categoria === "Bebidas" ? "🥤" : "🌯"}</span>
                          <b>{categoria}</b>
                          {cantidadCategoria > 0 && <small>{cantidadCategoria}</small>}
                        </button>
                      );
                    })}
                  </div>
                  <div className="product-card-grid-pos">
                    {productos.filter((producto) => producto.categoria === categoriaActiva).map((producto) => {
                      const cantidadEnOrden = mesaSeleccionada.orden
                        .filter((item) => item.id === producto.id && !item.pagado)
                        .reduce((acc, item) => acc + item.cantidad, 0);
                      return (
                        <button
                          key={producto.id}
                          className={`product-pos-card ${cantidadEnOrden > 0 ? "selected" : ""}`}
                          onClick={() => agregarProductoOrden(producto)}
                        >
                          <span className="product-pos-icon">{producto.categoria === "Tacos" ? "🌮" : producto.categoria === "Hamburguesas" ? "🍔" : producto.categoria === "Papas" ? "🍟" : producto.categoria === "Bebidas" ? "🥤" : "🌯"}</span>
                          <strong>{producto.nombre}</strong>
                          <small>{producto.descripcion}</small>
                          <b>{formatoCRC(producto.precio)}</b>
                          {cantidadEnOrden > 0 && <em>{cantidadEnOrden} en orden</em>}
                        </button>
                      );
                    })}
                  </div>
                </div>
              )}

              <div className="pos-order-panel">
                <div className="order-list-panel">
                  <div className="order-list-title">
                    <h2>Orden</h2>
                    <small>{mesaSeleccionada.orden.length} productos</small>
                  </div>
                  {mesaSeleccionada.orden.length === 0 && <p className="empty-order-text">Tocá un producto para agregarlo.</p>}
                  <div className="order-items-grid">
                    {mesaSeleccionada.orden.map((item) => {
                      const tieneModificaciones = Boolean(item.nota.trim() || item.sinIngredientes.length || item.extras.length);
                      return (
                        <div key={item.uid} className="order-item tile-order-item">
                          <div className="tile-order-header">
                            <div className="tile-order-title">
                              <h3>{item.cantidad}x {item.nombre} {item.enviadoComanda ? <span className="printed-badge">IMPRESO</span> : <span className="new-badge">NUEVO</span>}</h3>
                              <p>{item.descripcion}</p>
                            </div>
                            <b>{formatoCRC(precioLinea(item))}</b>
                          </div>

                          {tieneModificaciones && (
                            <div className="tile-order-summary">
                              {item.sinIngredientes.length > 0 && <span>SIN: {item.sinIngredientes.join(", ")}</span>}
                              {item.extras.length > 0 && <span>EXTRAS: {item.extras.map((extra) => `${extra.nombre} ${formatoCRC(extra.precio)}`).join(", ")}</span>}
                              {item.nota.trim() && <span>NOTA: {item.nota}</span>}
                            </div>
                          )}

                          <div className="tile-order-actions">
                            <details className="modifier-details inline-edit-details">
                              <summary>{puedeEditarItem(item) ? "▶ Editar" : "▶ Detalle"}</summary>
                              <div className="modifier-body inline-edit-body">
  <div className="edit-panel-top">
    <b>Modificar {item.nombre}</b>
    <button
      type="button"
      className="danger-mini edit-close-button"
      onClick={(e) => {
        e.preventDefault();
        e.stopPropagation();
        e.currentTarget.closest("details")?.removeAttribute("open");
      }}
    >
      Ocultar
    </button>
  </div>

  <textarea disabled={!puedeEditarItem(item)} value={item.nota} onChange={(e) => actualizarItem(item.uid, { nota: e.target.value })} placeholder="Nota para cocina" />{puedeEditarItem(item) ? (
                                  <div className="mod-grid compact-mod-grid">
                                    {item.ingredientes.map((ingrediente) => (
                                      <label key={ingrediente}><input type="checkbox" checked={item.sinIngredientes.includes(ingrediente)} onChange={() => toggleIngrediente(item, ingrediente)} /> Sin {ingrediente}</label>
                                    ))}
                                    {extrasDisponibles.map((extra) => (
                                      <label key={extra.nombre}><input type="checkbox" checked={item.extras.some((e) => e.nombre === extra.nombre)} onChange={() => toggleExtra(item, extra)} /> {extra.nombre} {formatoCRC(extra.precio)}</label>
                                    ))}
                                  </div>
                                ) : (
                                  <div className="read-only-mods">
                                    {item.sinIngredientes.length > 0 && <p><b>SIN:</b> {item.sinIngredientes.join(", ")}</p>}
                                    {item.extras.length > 0 && <p><b>EXTRAS:</b> {item.extras.map((extra) => `${extra.nombre} ${formatoCRC(extra.precio)}`).join(", ")}</p>}
                                    {item.nota.trim() && <p><b>NOTA:</b> {item.nota}</p>}
                                    {!tieneModificaciones && <p>Sin modificaciones.</p>}
                                  </div>
                                )}
                              </div>
                            </details>

                            <label className="carry-check">
                              <input
                                type="checkbox"
                                checked={item.consumo === "LLEVAR"}
                                disabled={!puedeMarcarLlevarItem(item)}
                                onChange={() => cambiarConsumoItem(item.uid, item.consumo === "LOCAL" ? "LLEVAR" : "LOCAL")}
                              />
                              Llevar
                            </label>

                            {puedeEditarItem(item) && (
                              <div className="qty-control tile-qty-control">
                                <button onClick={() => cambiarCantidad(item.uid, -1)}>-</button>
                                <span>{item.cantidad}</span>
                                <button onClick={() => cambiarCantidad(item.uid, 1)}>+</button>
                              </div>
                            )}

                            {puedeEditarItem(item) && <button className="danger-mini tile-delete-button" onClick={() => eliminarItem(item.uid)}>Eliminar</button>}
                          </div>
                        </div>
                      );
                    })}
                  </div>
                </div>

                <div className="pos-bottom-fixed">
                  <div className="totals-box">
                    <div><span>Subtotal</span><b>{formatoCRC(totalesMesa.subtotal)}</b></div>
                    <div><span>Total pendiente</span><b>{formatoCRC(totalesMesa.total)}</b></div>
                  </div>

                  {puedeCobrar && mesaSeleccionada.orden.some((item) => !item.pagado) && (
                    <div className="pay-box">
                      {!cajaAbierta ? <button onClick={abrirCaja} className="primary">Abrir caja</button> : null}
                      <button onClick={toggleCuentaDividida}>{mesaSeleccionada.cuentaDividida ? "Desactivar cuenta dividida" : "Cuenta dividida"}</button>
                      {mesaSeleccionada.cuentaDividida && mesaSeleccionada.orden.map((item) => !item.pagado && (
                        <label key={item.uid} className="pay-check"><input type="checkbox" checked={itemsPagoSeleccionados.includes(item.uid)} onChange={() => toggleItemPago(item.uid)} /> {item.nombre}</label>
                      ))}
                      <select value={metodoPago} onChange={(e) => setMetodoPago(e.target.value as MetodoPago)}><option>Efectivo</option><option>Tarjeta</option><option>SINPE</option><option>Mixto</option></select>
                      {pagoUsaEfectivo && (
                        <div className="cash-change-box">
                          <input type="number" value={montoRecibido} onChange={(e) => setMontoRecibido(Number(e.target.value))} placeholder="Monto recibido" />
                          <div className="cash-quick-buttons">
                            {[5000, 10000, 20000].map((monto) => <button key={monto} type="button" onClick={() => setMontoRecibido(monto)}>{formatoCRC(monto)}</button>)}
                          </div>
                          <div className="change-summary">
                            <span>Recibido: <b>{formatoCRC(montoRecibido)}</b></span>
                            <span>Vuelto: <b>{formatoCRC(vueltoActual)}</b></span>
                          </div>
                        </div>
                      )}
                      <h2>A cobrar: {formatoCRC(totalesCobro.total)}</h2>
                    </div>
                  )}

                  <div className="actions-row bottom-actions">
                    {(esJefe || esAdmin || esMesero || esCaja) && <button className="primary" onClick={enviarComanda}>Imprimir comanda</button>}
                    {(esJefe || esAdmin || esMesero || esCaja) && <button onClick={solicitarCuenta}>Solicitar cuenta</button>}
                    {puedeCobrar && <button className="blue" onClick={cajaAbierta ? cobrar : abrirCaja} disabled={!itemsCobroActual.length}>{cajaAbierta ? "Cobrar / imprimir factura" : "Abrir caja para cobrar"}</button>}
                  </div>
                </div>
              </div>
            </div>
          </section>
        )}

        {vista === "caja" && puedeCobrar && (
          <section className="page no-print">
            <div className="page-title">
              <div>
                <h1>Caja y cierre de turno</h1>
                <p>{puedeVerCajaDetallada ? "La apertura es fondo para vuelto. No cuenta como venta ni ganancia." : "Este rol solo puede cobrar y consultar el último cierre."}</p>
              </div>
              {puedeVerCajaDetallada ? (
                <div className="actions-row">
                  <button type="button" onClick={probarImpresoraLocal}>Probar impresora</button>
                  {!cajaAbierta ? (
                    <button className="primary" onClick={abrirCaja}>Abrir caja</button>
                  ) : (
                    <>
                      <button onClick={registrarSalida}>Registrar salida</button>
                      <button onClick={() => setMostrarDetalleTurno(true)}>Ver detalle del turno</button>
                      <button className="danger" onClick={cerrarCaja}>Cerrar turno</button>
                    </>
                  )}
                </div>
              ) : puedeAbrirCerrarCaja ? (
                <div className="actions-row">
                  <button type="button" onClick={probarImpresoraLocal}>Probar impresora</button>
                  {!cajaAbierta ? (
                    <button className="primary" onClick={abrirCaja}>Abrir caja</button>
                  ) : (
                    <button className="danger" onClick={cerrarCaja}>Cerrar caja</button>
                  )}
                </div>
              ) : null}
            </div>

            {puedeVerCajaDetallada ? (
              <div className="panel caja-status-panel">
                <h2>{cajaAbierta ? "Turno abierto" : "Caja cerrada"}</h2>
                {cajaAbierta ? (
                  <>
                    <p><b>Abrió:</b> {cajaActual?.usuario} · {cajaActual?.fechaApertura}</p>
                    <p><b>Fondo inicial para vuelto:</b> {formatoCRC(cajaActual?.montoApertura || 0)}. Este monto solo sirve para dar vuelto.</p>
                    <p><b>Efectivo físico esperado:</b> {formatoCRC(efectivoEsperadoTurno)} = fondo inicial + ventas en efectivo - salidas.</p>
                    <p><b>Total vendido real:</b> {formatoCRC(totalVendido)}. Aquí no se suma la apertura y no se restan salidas.</p>
                  </>
                ) : (
                  <p>No hay turno abierto. Abrí caja antes de cobrar ventas.</p>
                )}
              </div>
            ) : (
              <div className="panel caja-status-panel restricted-caja-panel">
                <h2>{cajaAbierta ? "Caja abierta" : "Caja cerrada"}</h2>
                <p>Este rol no puede ver montos del turno, movimientos, salidas, efectivo esperado ni detalles históricos de cierre.</p>
                <p>{cajaAbierta ? "Podés tomar pedidos, cobrar desde Mesas y órdenes y cerrar caja." : "Podés abrir caja para iniciar cobros. El último cierre solo se muestra cuando la caja está cerrada."}</p>
              </div>
            )}

            {cajaAbierta && puedeVerCajaDetallada && (
              <div className="panel movements-preview">
                <div className="section-title-row">
                  <h2>Últimos movimientos del turno</h2>
                  <button onClick={() => setMostrarDetalleTurno(true)}>Abrir ventana detallada</button>
                </div>
                {movimientosCaja.length === 0 && <p>Sin movimientos todavía.</p>}
                {movimientosCaja.slice(0, 6).map((mov) => (
                  <div key={mov.id} className={`movement-row movement-${mov.tipo.toLowerCase()}`}>
                    <div><b>{mov.tipo}</b><small>{mov.fecha} · {mov.usuario}</small><p>{mov.descripcion}</p></div>
                    <strong>{formatoCRC(mov.monto)}</strong>
                  </div>
                ))}
              </div>
            )}

            <div className="panel">
              <div className="section-title-row">
                <h2>{puedeVerCajaDetallada ? "Historial de cierres" : "Último cierre"}</h2>
              </div>
              {puedeVerCajaDetallada ? (
                cierresCaja.map((cierre) => (
                  <CierreCard
                    key={cierre.id}
                    cierre={cierre}
                    onDetalle={() => setCierreDetalle(cierre)}
                    onImprimir={() => imprimirCierre(cierre)}
                  />
                ))
              ) : cajaAbierta ? (
                <p>El último cierre se oculta mientras la caja está abierta.</p>
              ) : ultimoCierreVisibleCaja ? (
                <CierreResumenCajaCard
                  cierre={ultimoCierreVisibleCaja}
                  onDetalle={() => setCierreDetalle(ultimoCierreVisibleCaja)}
                  onImprimir={() => imprimirCierre(ultimoCierreVisibleCaja)}
                />
              ) : null}
              {puedeVerCajaDetallada ? (!ultimoCierre && <p>No hay cierres registrados.</p>) : (!cajaAbierta && !ultimoCierreVisibleCaja && <p>No hay cierre registrado del día.</p>)}
            </div>
          </section>
        )}

        {vista === "facturas" && puedeCobrar && (
          <section className="page no-print">
            <h1>Facturas y reimpresión</h1>
            {ventas.length === 0 && <p>No hay facturas del turno actual.</p>}
            {ventas.map((venta) => (
              <div key={venta.id} className="invoice-row">
                <div><b>Factura #{venta.cuenta}</b><small>{venta.fechaCierre} · {venta.mesa} · {venta.cliente}</small></div>
                <b>{formatoCRC(venta.total)}</b>
                <button onClick={() => reimprimirFactura(venta)}>Reimprimir</button>
              </div>
            ))}
          </section>
        )}

        {vista === "menu" && puedeEditarMenu && (
          <section className="page no-print">
            <div className="page-title"><div><h1>Menú Gato Calavera</h1><p>Estos productos son los que salen en POS, QR, comanda y factura.</p></div><button onClick={restaurarMenuGato}>Restaurar menú oficial</button></div>
            <div className="panel form-row">
              <input value={nuevoProducto.nombre} onChange={(e) => setNuevoProducto({ ...nuevoProducto, nombre: e.target.value })} placeholder="Nombre" />
              <select value={nuevoProducto.categoria} onChange={(e) => setNuevoProducto({ ...nuevoProducto, categoria: e.target.value as CategoriaProducto })}>{categoriasProducto.map((c) => <option key={c}>{c}</option>)}</select>
              <input value={nuevoProducto.descripcion} onChange={(e) => setNuevoProducto({ ...nuevoProducto, descripcion: e.target.value })} placeholder="Descripción" />
              <input type="number" value={nuevoProducto.precio} onChange={(e) => setNuevoProducto({ ...nuevoProducto, precio: Number(e.target.value) })} placeholder="Precio" />
              <button className="primary" onClick={crearProducto}>Crear producto</button>
            </div>
            <div className="admin-products">
              {productos.map((producto) => (
                <div key={producto.id}>
                  <input value={producto.nombre} onChange={(e) => actualizarProducto(producto.id, { nombre: e.target.value })} />
                  <select value={producto.categoria} onChange={(e) => actualizarProducto(producto.id, { categoria: e.target.value as CategoriaProducto })}>{categoriasProducto.map((c) => <option key={c}>{c}</option>)}</select>
                  <input value={producto.descripcion} onChange={(e) => actualizarProducto(producto.id, { descripcion: e.target.value })} />
                  <input type="number" value={producto.precio} onChange={(e) => actualizarProducto(producto.id, { precio: Number(e.target.value) })} />
                  <button className="danger-mini" onClick={() => eliminarProductoAdmin(producto.id)}>Eliminar</button>
                </div>
              ))}
            </div>
          </section>
        )}

        {vista === "usuarios" && puedeCrearUsuarios && (
          <section className="page no-print">
            <h1>Usuarios y roles</h1>
            <div className="panel form-row">
              <input value={nuevoUsuario.usuario} onChange={(e) => setNuevoUsuario({ ...nuevoUsuario, usuario: e.target.value })} placeholder="Usuario" />
              <input value={nuevoUsuario.nombre} onChange={(e) => setNuevoUsuario({ ...nuevoUsuario, nombre: e.target.value })} placeholder="Nombre" />
              <input value={nuevoUsuario.password} onChange={(e) => setNuevoUsuario({ ...nuevoUsuario, password: e.target.value })} placeholder="Contraseña" />
              <div className="role-checks">
                {rolesDisponibles.map((r) => (
                  <label key={r}><input type="checkbox" checked={normalizarRolesUsuario(nuevoUsuario).includes(r)} onChange={() => cambiarRolNuevoUsuario(r)} /> {r}</label>
                ))}
              </div>
              <button className="primary" onClick={crearUsuario}>Crear usuario</button>
            </div>
            {usuarios.map((u) => (
              <div key={u.usuario} className="user-row">
                <b>{u.usuario}</b>
                <input value={u.nombre} onChange={(e) => actualizarUsuario(u.usuario, { nombre: e.target.value })} />
                <input value={u.password} onChange={(e) => actualizarUsuario(u.usuario, { password: e.target.value })} />
                <div className="role-checks small">
                  {rolesDisponibles.map((r) => (
                    <label key={r}><input type="checkbox" checked={normalizarRolesUsuario(u).includes(r)} onChange={() => cambiarRolUsuarioExistente(u, r)} /> {r}</label>
                  ))}
                </div>
                <span className="role-summary">{textoRolesUsuario(u)}</span>
                <button className="danger-mini" onClick={() => eliminarUsuario(u.usuario)}>Eliminar</button>
              </div>
            ))}
          </section>
        )}

        {vista === "qr" && puedeGestionar && (
          <section className="page no-print qr-page">
            <div className="page-title"><div><h1>QR de mesas</h1><p>El QR abre el menú digital con el diseño oscuro que querías.</p></div><button className="primary" onClick={imprimirQR}>Imprimir QR</button></div>
            <div className="qr-grid">
              {mesas.filter((mesa) => !mesa.esParaLlevar).map((mesa) => {
                const url = crearUrlMenuQR(mesa.id);
                return <div key={mesa.id} className="qr-card"><h3>{mesa.nombre}</h3><QRCodeCanvas value={url} size={150} /><small>{url}</small><button onClick={() => copiarLinkQR(mesa.id)}>Copiar link</button></div>;
              })}
            </div>
          </section>
        )}

        {mostrarDetalleTurno && puedeVerCajaDetallada && (
          <DetalleTurnoActualModal
            ventas={ventas}
            salidas={salidasDinero}
            movimientos={movimientosCaja}
            fondoInicial={cajaActual?.montoApertura || 0}
            efectivoVentas={efectivoVentasTurno}
            efectivoEsperado={efectivoEsperadoTurno}
            totalVendido={totalVendido}
            totalSalidas={totalSalidasTurno}
            onClose={() => setMostrarDetalleTurno(false)}
          />
        )}

        {cierreDetalle && puedeVerDetalleCierre(cierreDetalle) && (
          <DetalleCierreModal
            cierre={cierreDetalle}
            onClose={() => setCierreDetalle(null)}
            onImprimir={() => imprimirCierre(cierreDetalle)}
          />
        )}

        <TicketPrint ticket={ticketActual} />
      </main>
    </div>
  );
}

function Stat({ title, value }: { title: string; value: string }) {
  return <div className="stat-card"><small>{title}</small><strong>{value}</strong></div>;
}

function CierreResumenCajaCard({ cierre, onDetalle, onImprimir }: { cierre: CierreCaja; onDetalle: () => void; onImprimir: () => void }) {
  return (
    <div className="cierre-card compact-cierre-card caja-limited-card">
      <div className="section-title-row">
        <div>
          <h3>{cierre.fecha}</h3>
          <p>Cierre registrado por {cierre.usuario}</p>
          <small>{cierre.cantidadVentas} ventas registradas. Caja puede ver este detalle hasta abrir caja de nuevo.</small>
        </div>
        <div className="actions-row">
          <button onClick={onDetalle}>Ver detalle</button>
          <button onClick={onImprimir}>Imprimir cierre</button>
        </div>
      </div>
    </div>
  );
}

function CierreCard({ cierre, onDetalle, onImprimir }: { cierre: CierreCaja; onDetalle: () => void; onImprimir: () => void }) {
  return (
    <div className="cierre-card compact-cierre-card">
      <div className="section-title-row">
        <div>
          <h3>{cierre.fecha}</h3>
          <p>{cierre.usuario} · {cierre.cantidadVentas} ventas · Total vendido {formatoCRC(cierre.totalGeneral)}</p>
          <small>Fondo inicial para vuelto: {formatoCRC(cierre.montoApertura)} · Diferencia: {formatoCRC(cierre.diferencia)}</small>
        </div>
        <div className="actions-row">
          <button onClick={onDetalle}>Ver detalle</button>
          <button onClick={onImprimir}>Imprimir cierre</button>
        </div>
      </div>
    </div>
  );
}

function DetalleTurnoActualModal({
  ventas,
  salidas,
  movimientos,
  fondoInicial,
  efectivoVentas,
  efectivoEsperado,
  totalVendido,
  totalSalidas,
  onClose,
}: {
  ventas: Venta[];
  salidas: SalidaDinero[];
  movimientos: MovimientoCaja[];
  fondoInicial: number;
  efectivoVentas: number;
  efectivoEsperado: number;
  totalVendido: number;
  totalSalidas: number;
  onClose: () => void;
}) {
  const productos = contarProductosVendidos(ventas);
  return (
    <div className="modal-backdrop no-print">
      <div className="detail-modal">
        <div className="section-title-row modal-title">
          <div>
            <h1>Detalle del turno actual</h1>
            <p>Movimientos completos antes de cerrar caja.</p>
          </div>
          <button className="danger-mini" onClick={onClose}>Cerrar</button>
        </div>

        <div className="detail-grid">
          <span>Fondo inicial para vuelto <b>{formatoCRC(fondoInicial)}</b></span>
          <span>Total vendido real <b>{formatoCRC(totalVendido)}</b></span>
          <span>Efectivo de ventas <b>{formatoCRC(efectivoVentas)}</b></span>
          <span>Salidas de caja <b>{formatoCRC(totalSalidas)}</b></span>
          <span>Efectivo físico esperado <b>{formatoCRC(efectivoEsperado)}</b></span>
        </div>

        <h2>Movimientos de caja</h2>
        {movimientos.length === 0 && <p>Sin movimientos registrados.</p>}
        {ordenarMovimientosCronologicos(movimientos).map((mov) => <MovimientoCajaRow key={mov.id} movimiento={mov} />)}

        <h2>Ventas detalladas</h2>
        {ventas.length === 0 && <p>Sin ventas.</p>}
        {ventas.map((venta) => <VentaDetalleRow key={venta.id} venta={venta} />)}

        <h2>Productos vendidos</h2>
        {Object.entries(productos).length === 0 && <p>Sin productos vendidos.</p>}
        {Object.entries(productos).map(([producto, cantidad]) => <p key={producto}><b>{producto}</b>: {cantidad}</p>)}

        <h2>Salidas de dinero</h2>
        {salidas.length === 0 && <p>Sin salidas registradas.</p>}
        {salidas.map((salida) => (
          <div key={salida.id} className="detail-line"><b>{formatoCRC(salida.monto)}</b><span>{salida.motivo}</span><small>{salida.fecha} · {salida.usuario}</small></div>
        ))}
      </div>
    </div>
  );
}

function DetalleCierreModal({ cierre, onClose, onImprimir }: { cierre: CierreCaja; onClose: () => void; onImprimir: () => void }) {
  const ventasDetalle = cierre.ventasDetalle || [];
  const salidasDetalle = cierre.salidasDetalle || [];
  const movimientos = cierre.movimientos || [];
  return (
    <div className="modal-backdrop no-print">
      <div className="detail-modal cierre-detail-modal">
        <div className="section-title-row modal-title">
          <div>
            <h1>Detalle completo del cierre</h1>
            <p>{cierre.fecha} · Cerrado por {cierre.usuario}</p>
          </div>
          <div className="actions-row">
            <button onClick={onImprimir}>Imprimir cierre</button>
            <button className="danger-mini" onClick={onClose}>Cerrar</button>
          </div>
        </div>

        <div className="detail-grid important-detail-grid">
          <span>Fondo inicial para vuelto <b>{formatoCRC(cierre.montoApertura)}</b><small>No cuenta como ganancia.</small></span>
          <span>Total vendido / ganado <b>{formatoCRC(cierre.totalGeneral)}</b><small>No incluye apertura.</small></span>
          <span>Efectivo de ventas <b>{formatoCRC(cierre.efectivoVentas)}</b></span>
          <span>Tarjeta <b>{formatoCRC(cierre.tarjeta)}</b></span>
          <span>SINPE <b>{formatoCRC(cierre.sinpe)}</b></span>
          <span>Mixto <b>{formatoCRC(cierre.mixto)}</b></span>
          <span>Salidas de caja <b>{formatoCRC(cierre.salidas)}</b><small>No se restan del total vendido.</small></span>
          <span>Efectivo físico esperado <b>{formatoCRC(cierre.efectivoEsperado)}</b><small>Fondo + efectivo ventas - salidas.</small></span>
          <span>Efectivo contado <b>{formatoCRC(cierre.efectivoReportado)}</b></span>
          <span>Diferencia <b>{formatoCRC(cierre.diferencia)}</b></span>
        </div>

        <h2>Movimientos completos</h2>
        {movimientos.length === 0 && <p>Este cierre viene de una versión anterior y no tiene movimientos guardados.</p>}
        {ordenarMovimientosCronologicos(movimientos).map((mov) => <MovimientoCajaRow key={mov.id} movimiento={mov} />)}

        <h2>Ventas / facturas del cierre</h2>
        {ventasDetalle.length === 0 && <p>Sin detalle de ventas guardado.</p>}
        {ventasDetalle.map((venta) => <VentaDetalleRow key={venta.id} venta={venta} />)}

        <h2>Productos vendidos</h2>
        {Object.entries(cierre.productosVendidos || {}).map(([producto, cantidad]) => <p key={producto}><b>{producto}</b>: {cantidad}</p>)}

        <h2>Salidas de dinero</h2>
        {salidasDetalle.length === 0 && <p>Sin salidas guardadas.</p>}
        {salidasDetalle.map((salida) => (
          <div key={salida.id} className="detail-line"><b>{formatoCRC(salida.monto)}</b><span>{salida.motivo}</span><small>{salida.fecha} · {salida.usuario}</small></div>
        ))}
      </div>
    </div>
  );
}

function MovimientoCajaRow({ movimiento }: { movimiento: MovimientoCaja }) {
  return (
    <div className={`movement-row movement-${movimiento.tipo.toLowerCase()}`}>
      <div>
        <b>{movimiento.tipo}</b>
        <small>{movimiento.fecha} · {movimiento.usuario}{movimiento.metodoPago ? ` · ${movimiento.metodoPago}` : ""}</small>
        <p>{movimiento.descripcion}</p>
        {movimiento.items?.map((item, idx) => <small key={`${item.nombre}-${idx}`}>{item.cantidad}x {item.nombre} · {item.consumo} · {formatoCRC(item.total)}</small>)}
      </div>
      <strong>{formatoCRC(movimiento.monto)}</strong>
    </div>
  );
}

function VentaDetalleRow({ venta }: { venta: Venta }) {
  return (
    <div className="venta-detail-row">
      <div className="section-title-row">
        <div>
          <b>Factura #{venta.cuenta}</b>
          <small>{venta.fechaCierre} · {venta.mesa} · {venta.cliente} · {venta.metodoPago} · Usuario: {venta.usuario}</small>
        </div>
        <strong>{formatoCRC(venta.total)}</strong>
      </div>
      {venta.items.map((item) => (
        <p key={item.uid}>{item.cantidad}x {item.nombre} · {item.consumo} · {formatoCRC(precioLinea(item))}</p>
      ))}
      <small>Subtotal {formatoCRC(venta.subtotal)} · Total {formatoCRC(venta.total)}</small>
    </div>
  );
}

function TicketPrint({ ticket }: { ticket: Ticket | null }) {
  if (!ticket) return <div id="recibo" />;

  if (ticket.tipo === "comanda") {
    return (
      <div id="recibo" className="ticket comanda-ticket">
        <div className="ticket-logo"><img src={logoTicketDataUri} alt="Gato Calavera" /></div>
        <h1>COMANDA</h1>
        <h2>{new Date().toLocaleDateString("es-CR")}</h2>
        <h2>{ticket.mesa.tipoOrden === "LLEVAR" ? "LLEVAR" : ticket.mesa.nombre}</h2>
        <p><b>A nombre de:</b> {ticket.mesa.cliente || "Cliente"}</p>
        <p><b>Salonero:</b> {ticket.usuario}</p>
        <p><b>Hora:</b> {ticket.fecha}</p>
        <p><b>Mesa:</b> {ticket.mesa.nombre}</p>
        <p><b>Pacayas</b></p>
        <hr />
        <div className="ticket-head"><b>Cant.</b><b>Descripción</b></div>
        <hr />
        {ticket.items.map((item) => (
          <div key={item.uid} className="ticket-item">
            <p><b>{item.cantidad}</b> {item.nombre}</p>
            {item.consumo === "LLEVAR" && <small>PARA LLEVAR</small>}
            {item.sinIngredientes.length > 0 && <small>SIN: {item.sinIngredientes.join(", ")}</small>}
            {item.extras.length > 0 && <small>EXTRA: {item.extras.map((e) => e.nombre).join(", ")}</small>}
            {item.nota && <small>NOTA: {item.nota}</small>}
          </div>
        ))}
        <hr />
        <h2>*****ULTIMA LÍNEA*****</h2>
      </div>
    );
  }

  if (ticket.tipo === "cierre") {
    const cierre = ticket.cierre;
    const movimientos = ordenarMovimientosCronologicos(cierre.movimientos || []);
    const ventasDetalle = cierre.ventasDetalle || [];
    const salidasDetalle = cierre.salidasDetalle || [];
    return (
      <div id="recibo" className="ticket cierre-ticket-print">
        <div className="ticket-logo"><img src={logoTicketDataUri} alt="Gato Calavera" /></div>
        <h1>GATO CALAVERA</h1>
        <h2>CIERRE DE TURNO</h2>
        <p>{cierre.fecha}</p>
        <p><b>Usuario:</b> {cierre.usuario}</p>
        <hr />
        <p className="total-line"><span>Fondo vuelto:</span><b>{formatoCRC(cierre.montoApertura)}</b></p>
        <small>No cuenta como ganancia.</small>
        <p className="total-line"><span>Total vendido:</span><b>{formatoCRC(cierre.totalGeneral)}</b></p>
        <p className="total-line"><span>Efectivo ventas:</span><b>{formatoCRC(cierre.efectivoVentas)}</b></p>
        <p className="total-line"><span>Tarjeta:</span><b>{formatoCRC(cierre.tarjeta)}</b></p>
        <p className="total-line"><span>SINPE:</span><b>{formatoCRC(cierre.sinpe)}</b></p>
        <p className="total-line"><span>Mixto:</span><b>{formatoCRC(cierre.mixto)}</b></p>
        <p className="total-line"><span>Salidas:</span><b>{formatoCRC(cierre.salidas)}</b></p>
        <p className="total-line"><span>Esperado caja:</span><b>{formatoCRC(cierre.efectivoEsperado)}</b></p>
        <p className="total-line"><span>Contado:</span><b>{formatoCRC(cierre.efectivoReportado)}</b></p>
        <p className="total-line"><span>Diferencia:</span><b>{formatoCRC(cierre.diferencia)}</b></p>
        <hr />
        <h2>MOVIMIENTOS</h2>
        {movimientos.map((mov) => (
          <div key={mov.id} className="ticket-movement">
            <p><b>{mov.tipo}</b> {mov.fecha}</p>
            <small>{mov.descripcion}</small>
            <p className="total-line"><span>{mov.metodoPago || ""}</span><b>{formatoCRC(mov.monto)}</b></p>
          </div>
        ))}
        <hr />
        <h2>VENTAS</h2>
        {ventasDetalle.map((venta) => (
          <div key={venta.id} className="ticket-movement">
            <p><b>Factura #{venta.cuenta}</b> {venta.mesa}</p>
            <small>{venta.cliente} · {venta.metodoPago}</small>
            {venta.items.map((item) => <small key={item.uid}>{item.cantidad}x {item.nombre} · {formatoCRC(precioLinea(item))}</small>)}
            <p className="total-line"><span>Total:</span><b>{formatoCRC(venta.total)}</b></p>
          </div>
        ))}
        <hr />
        <h2>PRODUCTOS</h2>
        {Object.entries(cierre.productosVendidos || {}).map(([producto, cantidad]) => <p key={producto}>{producto}: {cantidad}</p>)}
        <hr />
        <h2>SALIDAS</h2>
        {salidasDetalle.length === 0 && <p>Sin salidas</p>}
        {salidasDetalle.map((salida) => <p key={salida.id}>{salida.fecha} · {salida.motivo} · {formatoCRC(salida.monto)}</p>)}
        <hr />
        <h2>******** FIN CIERRE ********</h2>
      </div>
    );
  }

  const venta = ticket.venta;
  return (
    <div id="recibo" className="ticket factura-ticket">
      <div className="ticket-logo"><img src={logoTicketDataUri} alt="Gato Calavera" /></div>
      <h1>GATO CALAVERA</h1>
      <h2>COMIDA MEXICANA</h2>
      <p>Gato Calavera Pacayas</p>
      <p>Alessandro Rubí Silesky</p>
      <p>ID No: 1-1835-0862</p>
      <p>alessandrorubi6@gmail.com</p>
      <p>Teléfono: 7229-3155</p>
      <h1>FACTURA</h1>
      <br />
      <p><b>Fecha apertura:</b> {venta.fechaApertura}</p>
      <p><b>Fecha cierre:</b> {venta.fechaCierre}</p>
      <p><b>Cuenta:</b> {venta.cuenta} &nbsp;&nbsp; <b>Mesa:</b> {venta.mesa}</p>
      <p><b>Invitados:</b> {venta.invitados}</p>
      <p><b>ID Cliente:</b></p>
      <p><b>Nombre:</b> {venta.cliente}</p>
      <hr />
      <div className="ticket-head"><b>Descripción</b><b>Precio</b></div>
      <hr />
      {venta.items.map((item) => (
        <div key={item.uid} className="fact-line">
          <span>{item.cantidad > 1 ? `${item.cantidad}x ` : ""}{item.nombre}</span><b>{formatoCRC(precioLinea(item))}</b>
          {item.consumo === "LLEVAR" && <small>Para llevar</small>}
          {item.sinIngredientes.length > 0 && <small>SIN: {item.sinIngredientes.join(", ")}</small>}
          {item.extras.length > 0 && <small>EXTRAS: {item.extras.map((e) => `${e.nombre} ${formatoCRC(e.precio)}`).join(", ")}</small>}
          {item.nota && <small>Nota: {item.nota}</small>}
        </div>
      ))}
      <hr />
      <p className="total-line"><span>SubTotal:</span><b>{formatoCRC(venta.subtotal)}</b></p>
      <p className="total-line"><span>Total:</span><b>{formatoCRC(venta.total)}</b></p>
      {(venta.metodoPago === "Efectivo" || venta.metodoPago === "Mixto") && (
        <>
          <p className="total-line"><span>Recibido:</span><b>{formatoCRC(venta.montoRecibido)}</b></p>
          <p className="total-line change-line"><span>Vuelto:</span><b>{formatoCRC(venta.vuelto)}</b></p>
        </>
      )}
      <br />
      <p><b>Condición de venta:</b> Contado</p>
      <p><b>Método de pago:</b> {venta.metodoPago}</p>
      <hr />
      <p><b>Moneda:</b> CRC</p>
      <hr />
      <h2>Régimen de Tributación simplificada</h2>
    </div>
  );
}
